package com.celik.kingdoms;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.celik.kingdoms.Rules.*;
import java.util.*;
class RulesTest {
 State s;Kingdom a,b,c;UUID mayorA,mayorB,memberB;
 Kingdom kingdom(String name,UUID owner){Kingdom k=new Kingdom();k.name=name;k.members.put(owner,"owner");k.mayors.add(owner);k.claims.add("minecraft:overworld|"+s.kingdoms.size()+"|0");s.kingdoms.put(k.id,k);return k;}
 @BeforeEach void setup(){s=new State();mayorA=UUID.randomUUID();mayorB=UUID.randomUUID();memberB=UUID.randomUUID();a=kingdom("A",mayorA);b=kingdom("B",mayorB);b.members.put(memberB,"member");c=kingdom("C",UUID.randomUUID());}
 War start(){War w=new War();w.first=a.id;w.second=b.id;w.startedAt=100;w.endsAt=1000;s.wars.add(w);return w;}
 @Test void tributeKeepsSmallCreditsAndAvoidsOverflow(){int remainder=0;long total=0;for(int i=0;i<10;i++){Tribute t=tribute(1,20,remainder);total+=t.amount();remainder=t.remainder();}assertEquals(2,total);assertEquals(0,remainder);assertEquals(Long.MAX_VALUE,tribute(Long.MAX_VALUE,100,0).amount());}
 @Test void kingdomColorsMigrateAndPersist(){Store store=new Store(java.nio.file.Path.of("unused"));store.validate(s);int color=a.highlightColor;assertEquals(highlightColor(a.id),color);assertEquals(color,store.copy(s).kingdoms.get(a.id).highlightColor);a.highlightColor=-1;store.validate(s);assertEquals(color,a.highlightColor);a.highlightColor=0x123456;store.validate(s);assertEquals(0x123456,store.copy(s).kingdoms.get(a.id).highlightColor);a.highlightColor=0x1000000;assertThrows(IllegalStateException.class,()->store.validate(s));}
 @Test void coreGlowTracksTheHostActiveWar(){a.core=new Core();c.core=new Core();c.core.tributeTo=b.id;assertFalse(CoreHighlight.wartime(s,a,500));War war=start();war.startedAt=700;assertFalse(CoreHighlight.wartime(s,a,500));assertTrue(CoreHighlight.wartime(s,a,700));assertTrue(CoreHighlight.wartime(s,c,700));assertFalse(CoreHighlight.wartime(s,a,1000));a.core.carried=true;assertFalse(CoreHighlight.wartime(s,a,800));}
 @Test void dustOutlineCoversEveryEdge(){var points=CoreHighlight.dustPoints(new net.minecraft.core.BlockPos(0,0,0));assertEquals(92,points.size());assertEquals(12,CoreHighlight.edges(net.minecraft.core.BlockPos.ZERO).size());for(var point:points){int boundary=(Math.abs(point.x+.015)<1e-9||Math.abs(point.x-1.015)<1e-9?1:0)+(Math.abs(point.y+.015)<1e-9||Math.abs(point.y-1.015)<1e-9?1:0)+(Math.abs(point.z+.015)<1e-9||Math.abs(point.z-1.015)<1e-9?1:0);assertTrue(boundary>=2,"dust stays on cube edges");}Config cfg=new Config();cfg.coreHighlightRange=0;assertThrows(IllegalArgumentException.class,cfg::validate);}
 @Test void coreLocationsAndCaptorsValidate(){a.core=new Core();a.core.dimension="minecraft:overworld";a.core.x=8;a.core.y=64;a.core.z=8;Store store=new Store(java.nio.file.Path.of("unused"));store.validate(s);a.core.tributeTo=b.id;assertTrue(holdsForeignCore(s,b.id));assertThrows(IllegalStateException.class,()->store.validate(s));a.core.x=24;store.validate(s);a.core.tributeTo=a.id;assertThrows(IllegalStateException.class,()->store.validate(s));}
 @Test void strictMajority(){assertFalse(majority(5,10));assertTrue(majority(6,10));assertFalse(majority(0,1));assertTrue(majority(1,1));assertTrue(majority(2,3));}
 @Test void mayorAndMajorityRequired(){assertNotNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB),500));assertNotNull(declarationFailure(s,a,b,mayorA,Set.of(memberB),500));assertNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB,memberB),500));}
 @Test void oneOfSeveralMayorsSuffices(){b.mayors.add(memberB);assertNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB,memberB),500));}
 @Test void nonMayorCannotDeclare(){assertNotNull(declarationFailure(s,a,b,UUID.randomUUID(),Set.of(mayorB,memberB),500));}
 @Test void protectionsAndCooldownApplyToBothSides(){for(Kingdom k:List.of(a,b)){k.protectedUntil=999;assertNotNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB,memberB),500));k.protectedUntil=0;k.cooldownUntil=999;assertNotNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB,memberB),500));k.cooldownUntil=0;}assertNull(declarationFailure(s,a,b,mayorA,Set.of(mayorB,memberB),1000));}
 @Test void reciprocalWarOverridesAllFlags(){start();for(Permission p:Permission.values()){if(p==Permission.DEPOSIT||p==Permission.WITHDRAW)continue;assertTrue(permitted(s,a,mayorB,p,500));assertTrue(permitted(s,b,mayorA,p,500));}for(Flag f:Flag.values())assertTrue(flag(s,b,f,500));}
 @Test void neutralPlayersCannotUseWarEvenWithPublicGrants(){start();b.publicPermissions.addAll(Arrays.asList(Permission.values()));b.publicPermissions.remove(Permission.DEPOSIT);b.publicPermissions.remove(Permission.WITHDRAW);for(Permission p:Permission.values())assertFalse(permitted(s,b,c.mayors.iterator().next(),p,500));}
 @Test void restrictionsReturnAtExactEnd(){start();assertFalse(permitted(s,b,mayorA,Permission.BREAK,1000));assertFalse(flag(s,b,Flag.FIRE,1000));}
 @Test void warHasNoLogoutTermination(){start();assertNotNull(war(s,a.id,999));assertNull(war(s,a.id,1000));}
 @Test void warDoesNotGrantTreasuryAccess(){start();assertFalse(permitted(s,b,memberB,Permission.WITHDRAW,500));assertFalse(permitted(s,b,mayorA,Permission.WITHDRAW,500));assertTrue(permitted(s,b,mayorB,Permission.WITHDRAW,500));}
 @Test void mayorCannotBypassDisabledFlagsAtPeace(){assertTrue(permitted(s,b,mayorB,Permission.PLACE,500));assertFalse(flag(s,b,Flag.FIRE,500));assertFalse(flag(s,b,Flag.EXPLOSIONS,500));}
 @Test void individualGrantsAreSpecific(){UUID guest=UUID.randomUUID();b.grants.put(guest,Set.of(Permission.BREAK));assertTrue(permitted(s,b,guest,Permission.BREAK,500));assertFalse(permitted(s,b,guest,Permission.PLACE,500));assertFalse(permitted(s,b,guest,Permission.WITHDRAW,500));}
 @Test void moneyAliasesAreExact(){assertEquals(1_000,MoneyInput.parsePositive("1k"));assertEquals(10_000_000,MoneyInput.parsePositive("10M"));assertEquals(1_500_000,MoneyInput.parsePositive("1.5m"));assertEquals(2_000_000,MoneyInput.parsePositive("2 million"));assertEquals(2_250,MoneyInput.parsePositive("$2.25K"));assertEquals(1_000_000_000,MoneyInput.parsePositive("1bil"));assertEquals(1_000,MoneyInput.parsePositive("1,000"));}
 @Test void moneyAliasesRejectInvalidOrFractionalResults(){assertThrows(IllegalArgumentException.class,()->MoneyInput.parsePositive("0"));assertThrows(IllegalArgumentException.class,()->MoneyInput.parsePositive("-1k"));assertThrows(IllegalArgumentException.class,()->MoneyInput.parsePositive("1.2345k"));assertThrows(IllegalArgumentException.class,()->MoneyInput.parsePositive("1z"));assertThrows(IllegalArgumentException.class,()->MoneyInput.parsePositive("999999999999999999999t"));}
 @Test void beaconLevelTwoCostsFourTimesMore(){Config cfg=new Config();cfg.beaconEffectFees.put("speed",125L);assertEquals(125,KingdomBeacon.cost(cfg,BeaconPower.SPEED,1));assertEquals(500,KingdomBeacon.cost(cfg,BeaconPower.SPEED,2));assertThrows(IllegalArgumentException.class,()->KingdomBeacon.cost(cfg,BeaconPower.BLINDNESS,2));}
 @Test void beaconEffectsPersistAndValidate(){BeaconEffect effect=new BeaconEffect();effect.sourceKingdom=a.id;effect.targetKingdom=a.id;effect.power=BeaconPower.HASTE;effect.level=2;effect.expiresAt=1000;s.beaconEffects.add(effect);Store store=new Store(java.nio.file.Path.of("unused"));State copy=store.copy(s);store.validate(copy);assertEquals(BeaconPower.HASTE,copy.beaconEffects.getFirst().power);copy.beaconEffects.getFirst().hostile=true;assertThrows(IllegalStateException.class,()->store.validate(copy));}
 @Test void spawnProtectionUsesChunkDistance(){assertEquals(0,KingdomService.chunkDistance(new net.minecraft.core.BlockPos(0,64,0),new net.minecraft.core.BlockPos(15,80,15)));assertEquals(1,KingdomService.chunkDistance(new net.minecraft.core.BlockPos(0,64,0),new net.minecraft.core.BlockPos(16,80,-1)));assertEquals(17,KingdomService.chunkDistance(new net.minecraft.core.BlockPos(0,64,0),new net.minecraft.core.BlockPos(272,80,0)));}
 @Test void starterProtectionDefaultsToTwentyFourHours(){Config cfg=new Config();assertEquals(16,cfg.spawnClaimProtectionChunks);assertEquals(1440,cfg.newKingdomProtectionMinutes);cfg.newKingdomProtectionMinutes=0;cfg.spawnClaimProtectionChunks=0;cfg.validate();}
 @Test void configRejectsUnsafeValues(){Config c=new Config();c.validate();c.warMinutes=0;assertThrows(IllegalArgumentException.class,c::validate);c.warMinutes=15;c.expansionFee=-1;assertThrows(IllegalArgumentException.class,c::validate);c.expansionFee=1;c.outpostClaimWeight=0;assertThrows(IllegalArgumentException.class,c::validate);}
 @Test void storeRoundTripAndOverlapDetection(){Store store=new Store(java.nio.file.Path.of("unused"));State copy=store.copy(s);store.validate(copy);assertEquals(3,copy.kingdoms.size());copy.kingdoms.get(a.id).claims.addAll(copy.kingdoms.get(b.id).claims);assertThrows(IllegalStateException.class,()->store.validate(copy));}
 @Test void acknowledgedIncidentIsKingdomWide(){b.overdueSince=100;b.warningAcknowledged=100;assertEquals(b.overdueSince,b.warningAcknowledged);b.overdueSince=200;assertNotEquals(b.overdueSince,b.warningAcknowledged);}
 @Test void claimRemovalMustKeepConnectivity(){assertTrue(KingdomService.connected(Set.of("minecraft:overworld|0|0","minecraft:overworld|1|0")));assertFalse(KingdomService.connected(Set.of("minecraft:overworld|0|0","minecraft:overworld|2|0")));}
 @Test void outpostsConsumeWeightedSlots(){a.claims.add("minecraft:overworld|10|0");a.outposts.add("minecraft:overworld|10|0");assertEquals(7,KingdomService.claimSlots(a,6));}
 @Test void outpostAnchorsPermitRemoteConnectedRegions(){Set<String> claims=Set.of("minecraft:overworld|0|0","minecraft:overworld|1|0","minecraft:overworld|10|0","minecraft:overworld|11|0");assertTrue(KingdomService.outpostTopology(claims,Set.of("minecraft:overworld|10|0")));assertFalse(KingdomService.outpostTopology(claims,Set.of()));}
 @Test void preparationKeepsClaimsProtected(){War w=start();w.startedAt=700;assertNull(war(s,a.id,500));assertNotNull(conflict(s,a.id,500));assertFalse(permitted(s,b,mayorA,Permission.BREAK,500));assertFalse(flag(s,b,Flag.FIRE,500));assertTrue(permitted(s,b,mayorA,Permission.BREAK,700));}
 @Test void preparationBlocksSecondDeclaration(){War w=start();w.startedAt=700;assertNotNull(declarationFailure(s,c,b,c.mayors.iterator().next(),Set.of(mayorB,memberB),500));}
 @Test void kingdomIdentityDefaultsAreStable(){assertEquals("minecraft:paper",new Kingdom().iconItem);assertEquals(a.name,a.display());a.displayName="The Realm";assertEquals("The Realm",a.display());}
 @Test void legacyTagFieldsDoNotDamageKingdomOrConfigData(){
  a.treasury=1234;var legacy=Store.JSON.toJsonTree(s).getAsJsonObject();legacy.getAsJsonObject("kingdoms").getAsJsonObject(a.id.toString()).addProperty("tag","OLD");
  State loaded=Store.JSON.fromJson(legacy,State.class);new Store(java.nio.file.Path.of("unused")).validate(loaded);Kingdom restored=loaded.kingdoms.get(a.id);
  assertEquals(a.members,restored.members);assertEquals(a.claims,restored.claims);assertEquals(a.treasury,restored.treasury);assertEquals(a.name,restored.display());assertFalse(Store.JSON.toJsonTree(restored).getAsJsonObject().has("tag"));
  var oldConfig=Store.JSON.toJsonTree(new Config()).getAsJsonObject();oldConfig.addProperty("maxTagLength",-1);oldConfig.addProperty("leaderboardShowTag",true);Config config=Store.JSON.fromJson(oldConfig,Config.class);config.validate();assertFalse(Store.JSON.toJsonTree(config).getAsJsonObject().has("maxTagLength"));assertFalse(Store.JSON.toJsonTree(config).getAsJsonObject().has("leaderboardShowTag"));
 }
 @Test void automationDefaultsOnAndCountdownValidates(){Config cfg=new Config();assertTrue(cfg.defaultFlags.contains(Flag.AUTOMATION));cfg.validate();cfg.warPreparationSeconds=-1;assertThrows(IllegalArgumentException.class,cfg::validate);}}
